func:
// ============================================
// FUNCTION NODE - Smart TeleHealth (Version FINALE corrigée)
// ============================================

let bpm = msg.payload.bpm;
let spo2 = msg.payload.spo2;
let temperature = msg.payload.temperature || msg.payload.temp;
let chute = msg.payload.chute || false;
let scenario = msg.payload.scenario || 0;

// Valeurs par défaut
if (bpm === undefined || bpm === null) bpm = 75;
if (spo2 === undefined || spo2 === null) spo2 = 98;
if (temperature === undefined || temperature === null) temperature = 37.0;

// Initialisation
let niveauAlerte = "stable";
let titreAlerte = "PATIENT STABLE";
let messageAlerte = "";
let actionRecommandee = "";

// ========== RÈGLES D'ALERTE (ordre prioritaire) ==========

// 1. CHUTE - Priorité maximale
if (chute === true) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - CHUTE DETECTEE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: OUI";
    actionRecommandee = "Contacter immédiatement le SAMU";
}

// 2. TACHYCARDIE CRITIQUE (BPM > 120)
else if (bpm > 120) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - TACHYCARDIE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Intervention médicale immédiate";
}

// 3. BRADYCARDIE (BPM < 50)
else if (bpm < 50) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - BRADYCARDIE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Intervention médicale immédiate";
}

// 4. HYPOXIE (SpO2 < 90%) - CORRIGÉ
else if (spo2 < 90) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - HYPOXIE";     // ✅ CORRECT: HYPOXIE
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Oxygène + contacter les urgences";
}

// 5. FIEVRE ELEVEE (> 38.5°C)
else if (temperature > 38.5) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - FIEVRE ELEVEE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Contacter le médecin";
}

// 6. HYPOTHERMIE (< 36.0°C)
else if (temperature < 36.0) {
    niveauAlerte = "urgence";
    titreAlerte = "URGENCE - HYPOTHERMIE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Couvrir le patient + médecin";
}

// 7. BPM ÉLEVÉ (100-120) - ALERTE
else if (bpm > 100) {
    niveauAlerte = "alerte";
    titreAlerte = "ALERTE - BPM ÉLEVÉ";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Surveillance renforcée, repos recommandé";
}

// 8. SpO2 BAS (90-94%) - ALERTE
else if (spo2 < 94) {
    niveauAlerte = "alerte";
    titreAlerte = "ALERTE - SpO2 BAS";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Surveillance renforcée";
}

// 9. TEMPÉRATURE ANORMALE (> 37.8 ou < 36.2)
else if (temperature > 37.8 || temperature < 36.2) {
    niveauAlerte = "alerte";
    titreAlerte = "ALERTE - TEMPÉRATURE ANORMALE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Surveillance et contrôle régulier";
}

// 10. STABLE
else {
    niveauAlerte = "stable";
    titreAlerte = "PATIENT STABLE";
    messageAlerte = "BPM: " + bpm + " | SpO2: " + spo2 + "% | Temp: " + temperature + "°C | Chute: NON";
    actionRecommandee = "Surveillance continue";
}

// ========== CONSTRUCTION DU MESSAGE DE SORTIE ==========

// Format pour msg.payload (ce que le nœud Debug affichera)
msg.payload = messageAlerte + " | " + actionRecommandee;

// Ajouter le titre séparément si besoin
msg.topic = "health/patient1/sensors";
msg.alerte = {
    niveau: niveauAlerte,
    titre: titreAlerte,
    message: messageAlerte,
    action: actionRecommandee,
    bpm: bpm,
    spo2: spo2,
    temperature: temperature,
    chute: chute,
    scenario: scenario
};

// Pour l'affichage dans le debug (optionnel - vous pouvez supprimer node.warn)
node.warn(titreAlerte + "+" + messageAlerte + "+" + actionRecommandee);

return msg;

// حفظ البيانات الأصلية في msg.originalData
msg.originalData = {
    bpm: msg.payload.bpm,
    spo2: msg.payload.spo2,
    temperature: msg.payload.temp || msg.payload.temperature,
    chute: msg.payload.chute || false
};

// البيانات للـ IA
msg.payload = {
    bpm: msg.originalData.bpm,
    spo2: msg.originalData.spo2,
    temperature: msg.originalData.temperature,
    chute: msg.originalData.chute
};

return msg;

let result = msg.payload.result;

// استرجاع البيانات الأصلية المحفوظة
let orig = msg.originalData || {};
let bpm         = orig.bpm;
let spo2        = orig.spo2;
let temperature = orig.temperature;
let chute       = orig.chute || false;

let labelMap = {0: "Stable", 1: "Stress", 2: "Critique"};
let colorMap = {Stable: "🟢", Stress: "🟠", Critique: "🔴"};

let etat   = labelMap[result.label];
let couleur = colorMap[etat];

let alertMessage = "";
let action = "";

if (result.label === 2) {
    alertMessage = "🚨 URGENCE MEDICALE !";
    action = "Contacter immediatement le SAMU";
} else if (result.label === 1) {
    alertMessage = "⚠️ ALERTE - Surveillance renforcee";
    action = "Repos recommande";
} else {
    alertMessage = "✅ Patient stable";
    action = "Surveillance continue";
}

msg.payload = {
    bpm: bpm,
    spo2: spo2,
    temperature: temperature,
    chute: chute,
    ia_result: {
        etat: etat,
        couleur: couleur,
        label: result.label,
        probabilites: result.probabilities
    },
    alerte: {
        niveau: result.label === 2 ? "CRITIQUE" : (result.label === 1 ? "STRESS" : "NORMAL"),
        message: alertMessage,
        action: action,
        timestamp: new Date().toISOString()
    }
};

return msg;

// Récupérer les données depuis le message entrant
let bpm = msg.payload.bpm;
let spo2 = msg.payload.spo2;
let temperature = msg.payload.temp || msg.payload.temperature;
let chute = msg.payload.chute || false;

// --- Récupérer l'état IA ---
// L'état IA peut venir de différents endroits selon votre flow
// Si "Format for ThingsBoard" est connecté APRÈS "Process IA Result"
let iaResult = msg.payload.result || msg.payload.ia_result || msg.payload;
let labelMap = {0: "Stable", 1: "Stress", 2: "Critique"};
let etatIA = labelMap[iaResult.label] || "Inconnu";

// --- Probabilités (optionnel) ---
let probaStable = iaResult.probabilities?.["0"] || iaResult.probabilites?.["0"] || 0;
let probaStress = iaResult.probabilities?.["1"] || iaResult.probabilites?.["1"] || 0;
let probaCritique = iaResult.probabilities?.["2"] || iaResult.probabilites?.["2"] || 0;

// --- Construction du message pour ThingsBoard ---
msg.payload = {
    bpm: bpm,
    spo2: spo2,
    temperature: temperature,
    chute: chute ? 1 : 0,
    etat_ia: etatIA,                                // ← Clé qui apparaîtra
    probabilite_stable: probaStable,
    probabilite_stress: probaStress,
    probabilite_critique: probaCritique
};

msg.topic = "v1/devices/me/telemetry";

// Debug : affiche dans la console Node-RED
node.warn("Envoi à ThingsBoard: " + JSON.stringify(msg.payload));

return msg;

let bpm         = msg.payload.bpm;
let spo2        = msg.payload.spo2;
let temperature = msg.payload.temperature;
let chute       = msg.payload.chute || false;
let iaResult    = msg.payload.ia_result || {};
let label       = iaResult.label !== undefined ? iaResult.label : 0;
let etat        = label === 2 ? "Critique" : (label === 1 ? "Stress" : "Stable");

node.warn("BPM=" + bpm + " etat=" + etat + " chute=" + chute);

if (label === 2 || label === 1 || chute === true) {

    let cause = "";
    if (chute)        cause = "CHUTE DETECTEE";
    else if (bpm > 120)   cause = "BPM CRITIQUE (" + bpm + ")";
    else if (bpm < 50)    cause = "BRADYCARDIE (" + bpm + ")";
    else if (spo2 < 90)   cause = "SPO2 CRITIQUE (" + spo2 + "%)";
    else if (label === 1) cause = "STRESS DETECTE";
    else cause = "ETAT CRITIQUE";

    let message = "🚨 ALERTE MEDICALE 🚨\n\n";
    message += "👤 Patient: Smart TeleHealth\n";
    message += "⚠️ Cause: " + cause + "\n\n";
    message += "❤️ BPM: " + bpm + "\n";
    message += "🫁 SpO2: " + spo2 + "%\n";
    message += "🌡️ Temp: " + temperature + "C\n";
    message += "🤸 Chute: " + (chute ? "OUI !" : "NON") + "\n";
    message += "🤖 IA: " + etat + "\n\n";
    message += "📱 Contactez les secours !";

    msg.payload = {
        chatId: 5607038234,
        type: "message",
        content: message
    };

    node.warn("TELEGRAM ENVOYE: " + cause);
    return msg;
}

node.warn("Stable - pas d'envoi");
return null;

// Récupérer le message reçu (ex: {"chatId":..., "type":..., "content":"Test inject direct"})
let content = msg.payload.content || "Message reçu";
let chatId = msg.payload.chatId || "";

// Formater pour ThingsBoard
msg.payload = {
    alerte_telegram: content,
    chat_id: chatId,
    timestamp_alerte: Date.now()
};

msg.topic = "v1/devices/me/telemetry";
return msg;
